package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// header is the fixed start of every generated file. It must stay POSIX sh:
// tv runs the file with `sh`.
const header = `# generated by tmux-save, edit freely
S=${S:-$(tmux display-message -p "#S")}
DIR=${DIR:-$PWD}

# Keys sent before the pane's shell has drawn its prompt are echoed but never
# run, so wait until the pane has output that has stopped changing.
wait_ready() {
	_i=0
	_prev=
	while [ "$_i" -lt 50 ]; do
		_cur=$(tmux capture-pane -p -t "$1" | tr -d '[:space:]')
		[ -n "$_cur" ] && [ "$_cur" = "$_prev" ] && return 0
		_prev=$_cur
		_i=$((_i + 1))
		sleep 0.1
	done
}

`

var sortbyRe = regexp.MustCompile(`^[a-z]+$`)

type generator struct {
	project string
	target  string // "=SESSION:"
	tree    *procTree
	out     strings.Builder

	// nvimSessions maps an nvim server socket to the session file (relative
	// to the project) already written for it, so panes attached to one
	// shared server reuse a single file.
	nvimSessions map[string]string

	// sharedVars maps a shared nvim server socket to the shell variable
	// that holds it in the generated script.
	sharedVars map[string]string
}

// sharedVar returns the script variable for a shared server's socket and
// whether this is the first time the server is seen.
func (g *generator) sharedVar(sock string) (string, bool) {
	if v, ok := g.sharedVars[sock]; ok {
		return v, false
	}
	if g.sharedVars == nil {
		g.sharedVars = map[string]string{}
	}
	v := fmt.Sprintf("_nvsock%d", len(g.sharedVars)+1)
	g.sharedVars[sock] = v
	return v, true
}

// sharedServerStart returns the script lines that bring a shared nvim server
// back on its original socket, loading the saved session. If a server still
// answers there it is reused untouched. The last line is a reaper that quits
// the server once the tmux session is gone, as tv does.
func sharedServerStart(v, sock, sessionRel string) []string {
	return []string{
		fmt.Sprintf(`%s=%s`, v, q(sock)),
		fmt.Sprintf(`if ! nvim --server "$%s" --remote-expr 1 >/dev/null 2>&1; then`, v),
		fmt.Sprintf(`	mkdir -p "$(dirname "$%s")"`, v),
		fmt.Sprintf(`	rm -f "$%s"`, v),
		fmt.Sprintf(`	setsid nvim --headless --listen "$%s" -S "$DIR"/%s </dev/null >/dev/null 2>&1 &`, v, q(sessionRel)),
		`	_i=0`,
		fmt.Sprintf(`	until nvim --server "$%s" --remote-expr 1 >/dev/null 2>&1 || [ "$_i" -ge 50 ]; do`, v),
		`		_i=$((_i + 1))`,
		`		sleep 0.1`,
		`	done`,
		fmt.Sprintf(`	setsid sh -c 'while tmux has-session -t "$1" 2>/dev/null; do sleep 30; done; nvim --server "$2" --remote-send ":qa!<CR>" 2>/dev/null; rm -f "$2"' _ "=$S:" "$%s" </dev/null >/dev/null 2>&1 &`, v),
		`fi`,
	}
}

// cleanSessionFiles removes session files from a previous save, so panes
// that no longer exist leave nothing behind.
func (g *generator) cleanSessionFiles() {
	old, _ := filepath.Glob(filepath.Join(g.project, sessionDirName, "nvim-*.vim"))
	for _, f := range old {
		os.Remove(f)
	}
}

// saveNvim writes a session file for the nvim behind pid and returns its
// path relative to the project.
func (g *generator) saveNvim(pid int, pane string) (string, bool) {
	server, ok := g.tree.nvimServer(pid)
	if !ok {
		return "", false
	}
	if rel, done := g.nvimSessions[server]; done {
		return rel, true
	}
	rel := filepath.Join(sessionDirName, "nvim-"+pane+".vim")
	if !saveNvimSession(server, filepath.Join(g.project, rel)) {
		return "", false
	}
	if g.nvimSessions == nil {
		g.nvimSessions = map[string]string{}
	}
	g.nvimSessions[server] = rel
	return rel, true
}

func (g *generator) line(format string, a ...any) {
	fmt.Fprintf(&g.out, format+"\n", a...)
}

// generate builds the whole restore script.
func (g *generator) generate() error {
	wins, err := listWindows(g.target)
	if err != nil {
		return err
	}
	g.out.WriteString(header)
	g.cleanSessionFiles()

	active := ""
	for i, w := range wins {
		if w.active {
			active = w.index
		}
		win := fmt.Sprintf(`"$S:%s"`, w.index)

		panes := listPanes(g.target, w.index)
		var cmds []string
		for j, p := range panes {
			dir := pathExpr(g.project, p.path)
			switch {
			case j == 0 && i == 0:
				g.line("tmux rename-window -t %s %s", win, q(w.name))
			case j == 0:
				g.line("tmux new-window -d -t %s -n %s -c %s", win, q(w.name), dir)
			default:
				g.line("tmux split-window -d -t %s -c %s", win, dir)
			}
			paneRef := fmt.Sprintf("%s.%d", w.index, p.index)
			if name, pid, ok := g.tree.findProg(p.pid); ok {
				// Whitelisted program: typed and run.
				live := fmt.Sprintf("%s%s", g.target, paneRef)
				cmds = append(cmds, g.relaunchPane(name, pid, paneRef, live)...)
			} else if args, ok := foregroundCmd(p.pid); ok {
				// Anything else that was running: typed, but not run.
				cmds = append(cmds,
					fmt.Sprintf(`wait_ready "$S:%s"`, paneRef),
					fmt.Sprintf(`tmux send-keys -t "$S:%s" -l -- "%s"`, paneRef, dq(shellWords(args))))
			}
		}
		if len(panes) > 1 {
			g.line("tmux select-layout -t %s %s", win, q(w.layout))
		}
		for _, c := range cmds {
			g.line("%s", c)
		}
		g.line("")
	}
	if active != "" {
		g.line(`tmux select-window -t "$S:%s"`, active)
	}
	return nil
}

// relaunchPane returns the restore steps for one program. For lf it reopens
// at the saved state: options, directory, filter, selection and cursor are
// replayed from a temp lfrc. Filters are per directory, so the script goes to
// the saved directory first and only then sets the filter and cursor.
func (g *generator) relaunchPane(name string, pid int, pane, live string) []string {
	tgt := "$S:" + pane
	cmds := []string{fmt.Sprintf(`wait_ready "%s"`, tgt)}

	if name == "claude" {
		// Resume the same conversation, from the directory it was started
		// in (claude looks sessions up by that directory).
		if id, dir, ok := claudeResume(pid); ok {
			cmds = append(cmds, fmt.Sprintf(`tmux send-keys -t "%s" "cd %s && claude --resume %s" C-m`,
				tgt, typedPath(g.project, dir), id))
			return cmds
		}
	}

	if name == "nvim" {
		args := cmdlineOf(pid)
		sock, shared := serverFromArgs(args)
		shared = shared && isRemoteUI(args)
		if rel, ok := g.saveNvim(pid, pane); ok {
			if !shared {
				return append(cmds, fmt.Sprintf(`tmux send-keys -t "%s" "nvim -S \"$DIR\"/%s" C-m`, tgt, dq(q(rel))))
			}
			// A client of a shared server: bring the server back (once per
			// server) with the saved session, then attach to it.
			v, first := g.sharedVar(sock)
			var out []string
			if first {
				out = append(out, sharedServerStart(v, sock, rel)...)
			}
			out = append(out, cmds...)
			return append(out, fmt.Sprintf(`tmux send-keys -t "%s" "nvim --server '$%s' --remote-ui" C-m`, tgt, v))
		}
	}

	if name == "lf" {
		if st, ok := queryLf(pid); ok {
			filter, _ := lfFilterFromScreen(live, st.file)

			cmds = append(cmds, `_lfrc=$(mktemp)`, `cat >"$_lfrc" <<LFRC_EOF`)
			cmds = append(cmds, boolOpt("hidden", st.hidden))
			if sortbyRe.MatchString(st.sortby) {
				cmds = append(cmds, "set sortby "+st.sortby)
			}
			cmds = append(cmds, boolOpt("reverse", st.reverse))
			cmds = append(cmds, boolOpt("dirfirst", st.dirfirst))
			cmds = append(cmds, fmt.Sprintf(`cd "%s"`, relToDir(g.project, st.cwd)))
			if filter != "" {
				cmds = append(cmds, "setfilter "+hdEsc(filter))
			}
			if len(st.selected) > 0 && st.selected[0] != "" {
				line := "toggle"
				for _, f := range st.selected {
					if f != "" {
						line += fmt.Sprintf(` "%s"`, relToDir(g.project, f))
					}
				}
				cmds = append(cmds, "unselect", line)
			}
			if st.file != "" {
				cmds = append(cmds, fmt.Sprintf(`select "%s"`, relToDir(g.project, st.file)))
			}
			cmds = append(cmds, "LFRC_EOF")
			cmds = append(cmds, fmt.Sprintf(`tmux send-keys -t "%s" "lf -command 'source $_lfrc' ; rm -f '$_lfrc'" C-m`, tgt))
			return cmds
		}
	}

	return append(cmds, fmt.Sprintf(`tmux send-keys -t "%s" "%s" C-m`, tgt, dq(relaunch[name])))
}

// boolOpt renders an lf boolean option as "set X" or "set noX".
func boolOpt(name, value string) string {
	if value == "true" {
		return "set " + name
	}
	return "set no" + name
}
